/**
 * Update the UI elements.
 *
 * @param {Number} totalScore The current total score.
 * @param {Number} totalMax The maximum possible score.
 */
const updateUi = (totalScore, totalMax) => {
    const score = +totalScore.toFixed(2);
    const max = +totalMax.toFixed(2);
    const percent = max > 0 ? (score / max) * 100 : 0;
    const displayPercent = +Math.max(0, Math.min(percent, 100)).toFixed(2);

    document.querySelectorAll('[data-region="total-mark-display"]').forEach(region => {
        // Update the text spans.
        region.querySelector('.total-score-text').textContent = score.toString();
        region.querySelector('.total-max-text').textContent = max.toString();
        region.querySelector('.total-percent').textContent = displayPercent.toString();

        // Update the progress bar.
        const bar = region.querySelector('.total-progress-bar');
        if (bar) {
            bar.style.width = displayPercent + '%';
            bar.setAttribute('aria-valuenow', score.toString());
            bar.setAttribute('aria-valuemax', max.toString());
        }
    });
};

/**
 * Calculate totals for Rubric.
 */
const calculateRubric = () => {
    const rubric = document.querySelector('.gradingform_rubric');
    if (!rubric) {
        return;
    }

    let runningTotal = 0;
    let runningMax = 0;

    rubric.querySelectorAll('.criterion').forEach(row => {
        const selected = row.querySelector('.level.checked .scorevalue');
        if (selected) {
            runningTotal += parseFloat(selected.textContent) || 0;
        }

        let rowMax = 0;
        row.querySelectorAll('.scorevalue').forEach(span => {
            const val = parseFloat(span.textContent) || 0;
            if (val > rowMax) {
                rowMax = val;
            }
        });
        runningMax += rowMax;
    });

    updateUi(runningTotal, runningMax);
};

const calculateRubricRanges = () => {
    const rubric = document.querySelector('.gradingform_rubric_ranges');
    if (!rubric) {
        return;
    }

    let runningTotal = 0;
    let runningMax = 0;

    rubric.querySelectorAll('.criterion').forEach(row => {
        // There might be a mix of ranged and non-ranged criteria.
        // If it's ranged, it will be in an input with class rangegrade.
        const points = row.querySelector('.points input.rangegrade');
        // If it's non ranged, it'll be like the rubric calculation function above.
        const scoreValue = row.querySelector('.level .scorevalue');

        // Ranged criterion.
        if (points) {
            runningTotal += parseFloat(points.value) || 0;
            runningMax += parseFloat(points.getAttribute('max')) || 0;
        } else if (scoreValue) {
            // Non-ranged criterion.
            const selected = row.querySelector('.level.checked .scorevalue');
            if (selected) {
                runningTotal += parseFloat(selected.textContent) || 0;
            }
            let rowMax = 0;
            row.querySelectorAll('.scorevalue').forEach(span => {
                const val = parseFloat(span.textContent) || 0;
                if (val > rowMax) {
                    rowMax = val;
                }
            });
            runningMax += rowMax;
        }
    });

    updateUi(runningTotal, runningMax);
};

/**
 * Calculate totals for Marking Guide.
 */
const calculateGuide = () => {
    const guide = document.querySelector('.gradingform_guide');
    if (!guide) {
        return;
    }

    let runningTotal = 0;
    let runningMax = 0;

    guide.querySelectorAll('.score input[id$="-score"]').forEach(input => {
        const val = parseFloat(input.value);
        const max = parseFloat(input.getAttribute('max'));
        if (!isNaN(val)) {
            runningTotal += Math.min(val, max);
        }
        if (!isNaN(max)) {
            runningMax += max;
        }
    });

    updateUi(runningTotal, runningMax);
};

/**
 * Initialize the grading tracker listeners.
 */
const initGradingTracker = () => {
    const rubric = document.querySelector('.gradingform_rubric');
    const guide = document.querySelector('.gradingform_guide');
    const rubricRanges = document.querySelector('.gradingform_rubric_ranges');

    if (rubric) {
        const observer = new MutationObserver(calculateRubric);
        observer.observe(rubric, {
            attributes: true,
            subtree: true,
            attributeFilter: ['class']
        });
        calculateRubric();
    }

    if (rubricRanges) {
        const observer = new MutationObserver(calculateRubricRanges);
        observer.observe(rubricRanges, {
            attributes: true,
            subtree: true,
            attributeFilter: ['class']
        });
        // Typed mark that stays within the already-selected level, so no class change happens.
        document.addEventListener('change', (e) => {
            if (e.target.closest('.gradingform_rubric_ranges .points input.rangegrade')) {
                calculateRubricRanges();
            }
        });
        calculateRubricRanges();
    }

    if (guide) {
        document.addEventListener('input', (e) => {
            if (e.target.closest('.gradingform_guide .score')) {
                calculateGuide();
            }
        });
        calculateGuide();
    }
};

/**
 * Init.
 */
export const init = () => {
    const run = () => {
        // A tiny 50ms delay to let the DOM settle.
        setTimeout(() => {
            initGradingTracker();
        }, 50);
    };

    if (document.readyState === 'complete') {
        run();
    } else {
        window.addEventListener('load', run);
    }
};